struct ListNode {
    int val;
    struct ListNode *next;
};

struct ListNode* newNode(int v) {
    struct ListNode* n = (struct ListNode*)malloc(sizeof(struct ListNode));
    n->val = v; n->next = NULL;
    return n;
}

struct ListNode* addTwoNumbers(struct ListNode* l1, struct ListNode* l2) {
    int s1[100], s2[100], n1=0, n2=0;
    while (l1) { s1[n1++] = l1->val; l1 = l1->next; }
    while (l2) { s2[n2++] = l2->val; l2 = l2->next; }
    int i=n1-1, j=n2-1, carry=0;
    struct ListNode* head=NULL;
    while (i>=0 || j>=0 || carry) {
        int sum=carry;
        if(i>=0) sum+=s1[i--];
        if(j>=0) sum+=s2[j--];
        struct ListNode* n=newNode(sum%10);
        n->next=head; head=n; carry=sum/10;
    }
    return head;
}

